import java.util.*;

public class Main {
    static List<List<Integer>> g = new ArrayList<>(), rg = new ArrayList<>();
    static List<Integer> order = new ArrayList<>();
    static boolean[] seen;
    static int[] comp;

    static void dfs1(int v) {            // pass 1: remember the finish order
        seen[v] = true;
        for (int w : g.get(v)) if (!seen[w]) dfs1(w);
        order.add(v);
    }

    static void dfs2(int v, int c) {     // pass 2: flood one SCC on the reversed graph
        comp[v] = c;
        for (int w : rg.get(v)) if (comp[w] < 0) dfs2(w, c);
    }

    public static void main(String[] args) {
        int n = 6;
        int[][] edges = {{0, 1}, {1, 2}, {2, 0}, {2, 3}, {3, 4}, {4, 3}, {5, 4}};
        StringBuilder sb = new StringBuilder("edges:");
        for (int i = 0; i < n; i++) { g.add(new ArrayList<>()); rg.add(new ArrayList<>()); }
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            rg.get(e[1]).add(e[0]);
            sb.append(" ").append(e[0]).append("->").append(e[1]);
        }
        System.out.println(sb);
        seen = new boolean[n];
        comp = new int[n];
        Arrays.fill(comp, -1);
        for (int v = 0; v < n; v++) if (!seen[v]) dfs1(v);
        int c = 0;                       // latest finisher first: SCC ids come out in topological order
        for (int i = n - 1; i >= 0; i--) if (comp[order.get(i)] < 0) dfs2(order.get(i), c++);
        // condensation: only edges that join two different SCCs survive
        boolean[] hasIn = new boolean[c], hasOut = new boolean[c];
        for (int[] e : edges) if (comp[e[0]] != comp[e[1]]) { hasOut[comp[e[0]]] = true; hasIn[comp[e[1]]] = true; }
        int sources = 0, sinks = 0;
        for (int i = 0; i < c; i++) { if (!hasIn[i]) sources++; if (!hasOut[i]) sinks++; }
        StringBuilder cs = new StringBuilder("SCC id of each node:");
        for (int v = 0; v < n; v++) cs.append(" ").append(comp[v]);
        System.out.println(cs);
        System.out.println("SCC count: " + c);
        System.out.println("condensation sources: " + sources + ", sinks: " + sinks);
        // a DAG becomes one big cycle after max(sources, sinks) extra edges
        System.out.println("edges to add to make it strongly connected: " + (c == 1 ? 0 : Math.max(sources, sinks)));
    }
}
// Time O(V + E), space O(V + E)

