    seen[v] = true;
    for (int w : g[v]) if (!seen[w]) dfs1(w);
    order_.push_back(v);
}

void dfs2(int v, int c) {     // pass 2: flood one SCC on the reversed graph
    comp[v] = c;
    for (int w : rg[v]) if (comp[w] < 0) dfs2(w, c);
}

int main() {
    int n = 6;
    vector<pair<int, int>> edges = {{0, 1}, {1, 2}, {2, 0}, {2, 3}, {3, 4}, {4, 3}, {5, 4}};
    g.assign(n, {}); rg.assign(n, {});
    cout << "edges:";
