        g[a].push_back(b);
        rg[b].push_back(a);
        cout << " " << a << "->" << b;
    }
    cout << "\n";
    seen.assign(n, false);
    comp.assign(n, -1);
    for (int v = 0; v < n; v++) if (!seen[v]) dfs1(v);
    int c = 0;                // latest finisher first: SCC ids come out in topological order
    for (int i = n - 1; i >= 0; i--) if (comp[order_[i]] < 0) dfs2(order_[i], c++);
    // condensation: only edges that join two different SCCs survive
    vector<bool> hasIn(c, false), hasOut(c, false);
    for (auto [a, b] : edges) if (comp[a] != comp[b]) { hasOut[comp[a]] = true; hasIn[comp[b]] = true; }
    int sources = 0, sinks = 0;
    for (int i = 0; i < c; i++) { if (!hasIn[i]) sources++; if (!hasOut[i]) sinks++; }
