import java.util.*;

public class Main {
    static List<List<Integer>> g = new ArrayList<>();
    static int[] disc, low;
    static boolean[] onStack;
    static Deque<Integer> stack = new ArrayDeque<>();
    static int timer = 0, count = 0;

    static void dfs(int v) {
        disc[v] = low[v] = timer++;          // visit time; low starts equal to it
        stack.push(v);
        onStack[v] = true;
        for (int w : g.get(v)) {
            if (disc[w] < 0) { dfs(w); low[v] = Math.min(low[v], low[w]); }
            else if (onStack[w]) low[v] = Math.min(low[v], disc[w]);   // edge back into the open part
        }
        if (low[v] == disc[v]) {             // v is the root of an SCC: pop it off the stack
            StringBuilder sb = new StringBuilder("SCC " + count++ + ":");
            int w;
            do { w = stack.pop(); onStack[w] = false; sb.append(" ").append(w); } while (w != v);
            System.out.println(sb);
        }
    }

    public static void main(String[] args) {
        int n = 8;
        int[][] edges = {{0, 1}, {1, 2}, {2, 0}, {2, 3}, {3, 4}, {4, 5}, {5, 3}, {6, 5}, {6, 7}, {7, 6}};
        StringBuilder sb = new StringBuilder("edges:");
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); sb.append(" ").append(e[0]).append("->").append(e[1]); }
        System.out.println(sb);
        disc = new int[n];
        low = new int[n];
        onStack = new boolean[n];
        Arrays.fill(disc, -1);
        // one DFS pass, no reversed graph; SCCs come out in reverse topological order
        for (int v = 0; v < n; v++) if (disc[v] < 0) dfs(v);
        System.out.println("SCC count: " + count);
    }
}
// Time O(V + E), space O(V)

