import java.util.*;

public class Main {
    static int[] eu = {0, 1, 2, 1, 3, 4, 5, 5}, ev = {1, 2, 0, 3, 4, 5, 3, 6};
    static List<List<Integer>> adj = new ArrayList<>();   // adj[v] = ids of edges touching v
    static int[] disc, low;
    static boolean[] isAP;
    static int timer = 0;
    static StringBuilder bridges = new StringBuilder();

    static void dfs(int v, int parentEdge) {
        disc[v] = low[v] = timer++;
        int children = 0;
        for (int id : adj.get(v)) {
            if (id == parentEdge) continue;              // skip only the edge we came by
            int w = eu[id] ^ ev[id] ^ v;                  // the other end of edge id
            if (disc[w] >= 0) { low[v] = Math.min(low[v], disc[w]); continue; }   // back edge
            children++;
            dfs(w, id);
            low[v] = Math.min(low[v], low[w]);
            if (low[w] > disc[v]) bridges.append(" ").append(eu[id]).append("-").append(ev[id]);  // subtree cannot reach v
            if (parentEdge != -1 && low[w] >= disc[v]) isAP[v] = true;   // subtree cannot get above v
        }
        if (parentEdge == -1 && children >= 2) isAP[v] = true;          // root rule
    }

    public static void main(String[] args) {
        int n = 7;
        StringBuilder sb = new StringBuilder("edges:");
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int id = 0; id < eu.length; id++) {
            adj.get(eu[id]).add(id);
            adj.get(ev[id]).add(id);
            sb.append(" ").append(eu[id]).append("-").append(ev[id]);
        }
        System.out.println(sb);
        disc = new int[n];
        low = new int[n];
        isAP = new boolean[n];
        Arrays.fill(disc, -1);
        for (int v = 0; v < n; v++) if (disc[v] < 0) dfs(v, -1);
        StringBuilder d = new StringBuilder("disc:"), l = new StringBuilder("low: "), ap = new StringBuilder("articulation points:");
        for (int v = 0; v < n; v++) {
            d.append(" ").append(disc[v]);
            l.append(" ").append(low[v]);
            if (isAP[v]) ap.append(" ").append(v);
        }
        System.out.println(d + "\n" + l);
        System.out.println("bridges:" + bridges);
        System.out.println(ap);
    }
}
// Time O(V + E), space O(V + E)

