import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 5;
        int[][] edges = {{0, 3}, {3, 4}, {0, 1}, {1, 2}, {2, 0}};
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        int[] diff = new int[n];                     // out-degree minus in-degree
        StringBuilder sb = new StringBuilder("edges:");
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            diff[e[0]]++;
            diff[e[1]]--;
            sb.append(" ").append(e[0]).append("->").append(e[1]);
        }
        System.out.println(sb);
        // degree test: at most one start (out - in = 1) and one end (in - out = 1)
        int start = edges[0][0], plus = 0, minus = 0;
        boolean ok = true;
        for (int v = 0; v < n; v++) {
            if (diff[v] == 1) { plus++; start = v; }
            else if (diff[v] == -1) minus++;
            else if (diff[v] != 0) ok = false;
        }
        ok = ok && plus == minus && plus <= 1;
        System.out.println("degree test passed: " + (ok ? "yes" : "no") + ", start = " + start);
        int[] next = new int[n];                     // next unused edge of each vertex
        Deque<Integer> stack = new ArrayDeque<>();
        List<Integer> path = new ArrayList<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int v = stack.peek();
            if (next[v] < g.get(v).size()) stack.push(g.get(v).get(next[v]++));   // walk an unused edge
            else path.add(stack.pop());              // stuck: v is final, written back to front
        }
        Collections.reverse(path);
        StringBuilder p = new StringBuilder("Euler path:");
        for (int v : path) p.append(" ").append(v);
        System.out.println(p);
        // fewer than E + 1 vertices means some edges were in another piece
        System.out.println("uses every edge: " + (ok && path.size() == edges.length + 1 ? "yes" : "no"));
    }
}
// Time O(V + E), space O(V + E)

