public class Main {
    static final int LOG = 4;                 // 2^4 = 16 > 9 nodes
    static int[][] up;
    static int[] depth;

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) { int t = u; u = v; v = t; }
        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++)         // lift the deeper node to the same depth
            if ((diff >> k & 1) == 1) u = up[k][u];
        if (u == v) return u;
        for (int k = LOG - 1; k >= 0; k--)    // jump both while the ancestors still differ
            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }
        return up[0][u];                      // one step below the LCA
    }

    public static void main(String[] args) {
        int[] parent = {0, 0, 0, 1, 1, 2, 4, 4, 7};   // parent[v] < v; the root 0 points to itself
        int n = parent.length;
        up = new int[LOG][n];
        depth = new int[n];
        StringBuilder sb = new StringBuilder("parent:");
        for (int v = 0; v < n; v++) {
            up[0][v] = parent[v];
            if (v > 0) depth[v] = depth[parent[v]] + 1;
            sb.append(" ").append(parent[v]);
        }
        System.out.println(sb);
        for (int k = 1; k < LOG; k++)         // 2^k-th ancestor = two jumps of 2^(k-1)
            for (int v = 0; v < n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
        int[][] queries = {{3, 6}, {6, 8}, {5, 8}, {7, 8}};
        for (int[] q : queries) {
            int a = lca(q[0], q[1]);
            int dist = depth[q[0]] + depth[q[1]] - 2 * depth[a];
            System.out.println("lca(" + q[0] + ", " + q[1] + ") = " + a + ", distance = " + dist);
        }
    }
}
// Build O(N log N) time and space; each query O(log N)

