public class Main {
    static final int N = 4;                       // 0 = S, 1 = A, 2 = B, 3 = T
    static int[][] cap;
    static boolean useReverse;

    // push up to 'limit' units from u to T along edges that still have room
    static int dfs(int u, int limit, boolean[] seen) {
        if (u == N - 1) return limit;
        seen[u] = true;
        for (int v = 0; v < N; v++) {
            if (seen[v] || cap[u][v] == 0) continue;
            int pushed = dfs(v, Math.min(limit, cap[u][v]), seen);
            if (pushed > 0) {
                cap[u][v] -= pushed;                      // forward residual shrinks
                if (useReverse) cap[v][u] += pushed;      // reverse edge: permission to undo
                return pushed;
            }
        }
        return 0;
    }

    static int maxFlow(boolean reverse) {
        cap = new int[][] {{0, 3, 2, 0}, {0, 0, 2, 2}, {0, 0, 0, 3}, {0, 0, 0, 0}};
        useReverse = reverse;
