import java.util.*;

public class Main {
    // BFS over edges with residual > 0; returns parent[] (-1 = not reached)
    static int[] bfs(int[][] res, int s) {
        int n = res.length;
        int[] par = new int[n];
        Arrays.fill(par, -1);
        par[s] = s;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v = 0; v < n; v++) if (par[v] < 0 && res[u][v] > 0) { par[v] = u; q.add(v); }
        }
        return par;
    }

    public static void main(String[] args) {
        int[][] cap = {{0, 4, 3, 0}, {0, 0, 2, 1}, {0, 0, 0, 6}, {0, 0, 0, 0}};
        int n = 4, s = 0, t = 3, flow = 0;
        int[][] res = new int[n][];
        for (int i = 0; i < n; i++) res[i] = cap[i].clone();
        System.out.println("edges: 0->1:4 0->2:3 1->2:2 1->3:1 2->3:6, S = 0, T = 3");
        while (true) {                                    // Edmonds-Karp
            int[] par = bfs(res, s);
            if (par[t] < 0) break;
            int push = Integer.MAX_VALUE;
            for (int v = t; v != s; v = par[v]) push = Math.min(push, res[par[v]][v]);
            for (int v = t; v != s; v = par[v]) { res[par[v]][v] -= push; res[v][par[v]] += push; }
            flow += push;
        }
        System.out.println("max flow = " + flow);
        int[] side = bfs(res, s);                         // what S can still reach = S side of the cut
        StringBuilder sb = new StringBuilder("S side:");
        for (int v = 0; v < n; v++) if (side[v] >= 0) sb.append(" ").append(v);
        System.out.println(sb);
        int cut = 0;
        // cut edges: original edges from a reached node to an unreached node (all full)
        for (int u = 0; u < n; u++)
            for (int v = 0; v < n; v++)
                if (side[u] >= 0 && side[v] < 0 && cap[u][v] > 0) {
                    System.out.println("cut edge " + u + "->" + v + " capacity " + cap[u][v]);
                    cut += cap[u][v];
                }
        System.out.println("cut capacity = " + cut + " (equals the max flow)");
    }
}
// Edmonds-Karp O(V * E^2) time; cut extraction one BFS; O(V^2) space for the matrix

