import java.util.*;

public class Main {
    static int n = 6, s = 0, t = 5;
    static List<Integer> to = new ArrayList<>(), cap = new ArrayList<>();
    static List<List<Integer>> adj = new ArrayList<>();
    static int[] level, it;

    static void addEdge(int u, int v, int c) {     // edge id and id ^ 1 are a forward/reverse pair
        adj.get(u).add(to.size()); to.add(v); cap.add(c);
        adj.get(v).add(to.size()); to.add(u); cap.add(0);
    }

    static boolean bfs() {                          // level = BFS distance from S in the residual graph
        level = new int[n];
        Arrays.fill(level, -1);
        level[s] = 0;
        Deque<Integer> q = new ArrayDeque<>();
        q.add(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int id : adj.get(u))
                if (cap.get(id) > 0 && level[to.get(id)] < 0) { level[to.get(id)] = level[u] + 1; q.add(to.get(id)); }
        }
        return level[t] >= 0;
    }

    static int dfs(int u, int limit) {              // only walk edges that go one level deeper
        if (u == t) return limit;
        for (; it[u] < adj.get(u).size(); it[u]++) {    // current-edge pointer: never retry a dead edge
            int id = adj.get(u).get(it[u]), v = to.get(id);
            if (cap.get(id) == 0 || level[v] != level[u] + 1) continue;
            int pushed = dfs(v, Math.min(limit, cap.get(id)));
            if (pushed > 0) { cap.set(id, cap.get(id) - pushed); cap.set(id ^ 1, cap.get(id ^ 1) + pushed); return pushed; }
        }
        return 0;
    }

    public static void main(String[] args) {
        int[][] edges = {{0, 1, 16}, {0, 2, 13}, {1, 2, 10}, {2, 1, 4}, {1, 3, 12}, {3, 2, 9}, {2, 4, 14}, {4, 3, 7}, {3, 5, 20}, {4, 5, 4}};
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        StringBuilder sb = new StringBuilder("edges:");
        for (int[] e : edges) { addEdge(e[0], e[1], e[2]); sb.append(" ").append(e[0]).append("->").append(e[1]).append(":").append(e[2]); }
        System.out.println(sb);
        int flow = 0, phases = 0, pushed;
        while (bfs()) {                             // one phase = one level graph + one blocking flow
            it = new int[n];
            int phaseFlow = 0;
            while ((pushed = dfs(s, Integer.MAX_VALUE)) > 0) phaseFlow += pushed;
            flow += phaseFlow;
            System.out.println("phase " + ++phases + ": distance S-T = " + level[t] + ", pushed " + phaseFlow);
        }
        System.out.println("max flow = " + flow);
    }
}
// Dinic: O(V^2 * E) time in general, O(V + E) space

