            int pushed = Dfs(v, Math.Min(limit, cap[id]));
            if (pushed > 0) { cap[id] -= pushed; cap[id ^ 1] += pushed; return pushed; }
        }
        return 0;
    }

    static void Main() {
        int[][] edges = { new[] {0, 1, 16}, new[] {0, 2, 13}, new[] {1, 2, 10}, new[] {2, 1, 4}, new[] {1, 3, 12},
                          new[] {3, 2, 9}, new[] {2, 4, 14}, new[] {4, 3, 7}, new[] {3, 5, 20}, new[] {4, 5, 4} };
        adj = new List<int>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int>();
        string head = "edges:";
        foreach (int[] e in edges) { AddEdge(e[0], e[1], e[2]); head += " " + e[0] + "->" + e[1] + ":" + e[2]; }
        Console.WriteLine(head);
        int flow = 0, phases = 0, pushed;
        while (Bfs()) {                             // one phase = one level graph + one blocking flow
            it = new int[n];
            int phaseFlow = 0;
            while ((pushed = Dfs(s, int.MaxValue)) > 0) phaseFlow += pushed;
            flow += phaseFlow;
            Console.WriteLine("phase " + ++phases + ": distance S-T = " + level[t] + ", pushed " + phaseFlow);
        }
