import java.util.*;

public class Main {
    static int maxFlow(int[][] res, int s, int t) {       // Edmonds-Karp on a capacity matrix
        int n = res.length, flow = 0;
        while (true) {
            int[] par = new int[n];
            Arrays.fill(par, -1);
            par[s] = s;
            Deque<Integer> q = new ArrayDeque<>();
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v = 0; v < n; v++) if (par[v] < 0 && res[u][v] > 0) { par[v] = u; q.add(v); }
            }
            if (par[t] < 0) return flow;
            int push = Integer.MAX_VALUE;
            for (int v = t; v != s; v = par[v]) push = Math.min(push, res[par[v]][v]);
            for (int v = t; v != s; v = par[v]) { res[par[v]][v] -= push; res[v][par[v]] += push; }
            flow += push;
        }
    }

    public static void main(String[] args) {
        int D = 3, P = 2, DAYS = 4;                       // days 0,1 = period 0; days 2,3 = period 1
        int[] maxShifts = {2, 2, 1};
        int[][] avail = {{0, 1, 2}, {1, 3}, {0, 3}};      // days each doctor can work
        int S = 0, T = 1 + D + D * P + DAYS;
        int[][] cap = new int[T + 1][T + 1];
        for (int d = 0; d < D; d++) {
            cap[S][1 + d] = maxShifts[d];                 // S -> doctor: total shifts
            for (int p = 0; p < P; p++) cap[1 + d][1 + D + d * P + p] = 1;   // one shift per period
            for (int x : avail[d]) cap[1 + D + d * P + x / 2][1 + D + D * P + x] = 1;  // only available days
            System.out.println("doctor " + d + ": max " + maxShifts[d] + " shifts, available " + Arrays.toString(avail[d]));
        }
        for (int x = 0; x < DAYS; x++) cap[1 + D + D * P + x][T] = 1;        // each day needs one doctor
        int flow = maxFlow(cap, S, T);
        System.out.println("max flow = " + flow + " of " + DAYS + " days -> " + (flow == DAYS ? "feasible" : "not feasible"));
        // a used (doctor, period) -> day edge shows up as residual 1 on the reverse edge
        for (int x = 0; x < DAYS; x++)
            for (int d = 0; d < D; d++)
                if (cap[1 + D + D * P + x][1 + D + d * P + x / 2] == 1)
                    System.out.println("day " + x + " -> doctor " + d);
    }
}
// Nodes: 2 + D + D*P + days; Edmonds-Karp O(V * E^2) time, O(V^2) space

