import java.util.*;

public class Main {
    static int[][] adj = {{0, 1}, {0}, {1, 2}, {2}};   // adj[left] = right vertices it likes
    static int[] matchR;                                // matchR[r] = left partner of r, or -1
    static boolean[] seen;

    // try to give left vertex u a partner; may push earlier owners to another choice
    static boolean tryKuhn(int u) {
        for (int r : adj[u]) {
            if (seen[r]) continue;
            seen[r] = true;                             // ask each right vertex once per round
            if (matchR[r] < 0 || tryKuhn(matchR[r])) {  // r is free, or its owner can move
                matchR[r] = u;
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int L = adj.length, R = 4, size = 0;
        matchR = new int[R];
        Arrays.fill(matchR, -1);
        for (int u = 0; u < L; u++) {
            System.out.println("L" + u + " likes " + Arrays.toString(adj[u]));
            seen = new boolean[R];                      // fresh marks for every left vertex
            if (tryKuhn(u)) size++;
        }
        StringBuilder sb = new StringBuilder("pairs:");
        for (int r = 0; r < R; r++) if (matchR[r] >= 0) sb.append(" L").append(matchR[r]).append("-R").append(r);
        System.out.println(sb);
        System.out.println("maximum matching = " + size);
        // Konig (bipartite only): min vertex cover = matching, max independent set = V - matching
        System.out.println("minimum vertex cover = " + size);
        System.out.println("maximum independent set = " + (L + R - size));
    }
}
// Time O(V * E), space O(V + E)

