code.java:
import java.util.*;

public class Main {
    static int n = 10;
    static int[] from = {0, 1, 2, 2, 3, 4, 5, 6, 6, 7, 8, 4}, to = {1, 2, 0, 3, 4, 5, 3, 5, 7, 6, 0, 9};
    static int[] comp;

    // CSR: neighbours of v are tgt[off[v] .. off[v+1]-1]; two flat int arrays, no objects
    static int[][] csr(int[] a, int[] b) {
        int[] off = new int[n + 1], tgt = new int[a.length];
        for (int x : a) off[x + 1]++;
        for (int v = 0; v < n; v++) off[v + 1] += off[v];
        int[] pos = off.clone();
        for (int i = 0; i < a.length; i++) tgt[pos[a[i]]++] = b[i];
        return new int[][] {off, tgt};
    }

    // BFS (no recursion) over nodes that have no SCC yet
    static boolean[] reach(int s, int[][] g) {
        boolean[] seen = new boolean[n];
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = s;
        seen[s] = true;
        while (head < tail) {
            int u = queue[head++];
            for (int i = g[0][u]; i < g[0][u + 1]; i++) {
                int v = g[1][i];
                if (!seen[v] && comp[v] < 0) { seen[v] = true; queue[tail++] = v; }
            }
        }
        return seen;
    }

    public static void main(String[] args) {
        int[][] fw = csr(from, to), bw = csr(to, from);
        comp = new int[n];
        Arrays.fill(comp, -1);
        int count = 0, trimmed = 0;
        // trim: a node with no in-edges or no out-edges is an SCC by itself
        for (int v = 0; v < n; v++)
            if (fw[0][v] == fw[0][v + 1] || bw[0][v] == bw[0][v + 1]) { comp[v] = count++; trimmed++; }
        // forward-backward: SCC of the pivot = (reachable from it) AND (can reach it)
        for (int p = 0; p < n; p++) {
            if (comp[p] >= 0) continue;
            boolean[] f = reach(p, fw), b = reach(p, bw);
            for (int v = 0; v < n; v++) if (f[v] && b[v]) comp[v] = count;
            count++;
        }
        System.out.println("CSR offsets: " + Arrays.toString(fw[0]));
        System.out.println("CSR targets: " + Arrays.toString(fw[1]));
        System.out.println("trimmed single-node SCCs: " + trimmed);
        System.out.println("SCC id of each node: " + Arrays.toString(comp));
        System.out.println("SCC count: " + count);
    }
}
// Two BFS per pivot: O((V + E) * number of SCCs) worst case, O(V + E) space; the BFS parts parallelise

