// CSR: neighbours of v are tgt[off[v] .. off[v+1]-1]; two flat int arrays, no objects
Csr csr(const vector<int>& a, const vector<int>& b) {
    Csr g{vector<int>(n + 1, 0), vector<int>(a.size())};
    for (int x : a) g.off[x + 1]++;
    for (int v = 0; v < n; v++) g.off[v + 1] += g.off[v];
    vector<int> pos = g.off;
    for (size_t i = 0; i < a.size(); i++) g.tgt[pos[a[i]]++] = b[i];
    return g;
}

// BFS (no recursion) over nodes that have no SCC yet
vector<bool> reach(int s, const Csr& g) {
    vector<bool> seen(n, false);
    vector<int> queue_ = {s};
    seen[s] = true;
    for (size_t head = 0; head < queue_.size(); head++) {
        int u = queue_[head];
        for (int i = g.off[u]; i < g.off[u + 1]; i++) {
            int v = g.tgt[i];
            if (!seen[v] && comp[v] < 0) { seen[v] = true; queue_.push_back(v); }
        }
    }
    return seen;
}

string show(const vector<int>& a) {
    string s = "[";
    for (size_t i = 0; i < a.size(); i++) s += (i ? ", " : "") + to_string(a[i]);
    return s + "]";
}

int main() {
    Csr fw = csr(from_, to_), bw = csr(to_, from_);
    comp.assign(n, -1);
    int count = 0, trimmed = 0;
    // trim: a node with no in-edges or no out-edges is an SCC by itself
    for (int v = 0; v < n; v++)
        if (fw.off[v] == fw.off[v + 1] || bw.off[v] == bw.off[v + 1]) { comp[v] = count++; trimmed++; }
    // forward-backward: SCC of the pivot = (reachable from it) AND (can reach it)
    for (int p = 0; p < n; p++) {
        if (comp[p] >= 0) continue;
        vector<bool> f = reach(p, fw), b = reach(p, bw);
        for (int v = 0; v < n; v++) if (f[v] && b[v]) comp[v] = count;
        count++;
    }
    cout << "CSR offsets: " << show(fw.off) << "\nCSR targets: " << show(fw.tgt) << "\n";
    cout << "trimmed single-node SCCs: " << trimmed << "\n";
    cout << "SCC id of each node: " << show(comp) << "\nSCC count: " << count << "\n";
    return 0;
}
// Two BFS per pivot: O((V + E) * number of SCCs) worst case, O(V + E) space; the BFS parts parallelise

