import java.util.*;

public class Main {
    static int N = 3;                                  // variables; node 2i = x_i, node 2i+1 = NOT x_i
    static List<List<Integer>> g = new ArrayList<>(), rg = new ArrayList<>();
    static List<Integer> order = new ArrayList<>();
    static boolean[] seen = new boolean[2 * N];
    static int[] comp = new int[2 * N];

    static void dfs1(int v) { seen[v] = true; for (int w : g.get(v)) if (!seen[w]) dfs1(w); order.add(v); }
    static void dfs2(int v, int c) { comp[v] = c; for (int w : rg.get(v)) if (comp[w] < 0) dfs2(w, c); }
    static String name(int lit) { return (lit % 2 == 1 ? "!x" : "x") + lit / 2; }

    public static void main(String[] args) {
        // (x0 or x1) (!x0 or x1) (!x1 or x2) (!x2 or !x0)
        int[][] clauses = {{0, 2}, {1, 2}, {3, 4}, {5, 1}};
        for (int i = 0; i < 2 * N; i++) { g.add(new ArrayList<>()); rg.add(new ArrayList<>()); }
        StringBuilder sb = new StringBuilder("clauses:");
        for (int[] c : clauses) {
            // (a or b) means: NOT a -> b and NOT b -> a; lit ^ 1 is the negation
            g.get(c[0] ^ 1).add(c[1]); rg.get(c[1]).add(c[0] ^ 1);
            g.get(c[1] ^ 1).add(c[0]); rg.get(c[0]).add(c[1] ^ 1);
            sb.append(" (").append(name(c[0])).append(" or ").append(name(c[1])).append(")");
        }
        System.out.println(sb);
        Arrays.fill(comp, -1);
        for (int v = 0; v < 2 * N; v++) if (!seen[v]) dfs1(v);
        int cnt = 0;                                   // Kosaraju: ids come out in topological order
        for (int i = 2 * N - 1; i >= 0; i--) if (comp[order.get(i)] < 0) dfs2(order.get(i), cnt++);
        boolean[] val = new boolean[N];
        boolean sat = true;
        for (int i = 0; i < N; i++) {
            if (comp[2 * i] == comp[2 * i + 1]) sat = false;    // x and NOT x imply each other
            val[i] = comp[2 * i] > comp[2 * i + 1];            // pick the literal that comes later
        }
        System.out.println("satisfiable: " + (sat ? "yes" : "no"));
        boolean all = true;
        for (int[] c : clauses) all &= (val[c[0] / 2] == (c[0] % 2 == 0)) || (val[c[1] / 2] == (c[1] % 2 == 0));
        StringBuilder a = new StringBuilder("assignment:");
        for (int i = 0; i < N; i++) a.append(" x").append(i).append("=").append(val[i] ? "true" : "false");
        System.out.println(a);
        System.out.println("all clauses hold: " + (all ? "yes" : "no"));
    }
}
// Time O(n + m), space O(n + m) for n variables and m clauses

