        // chain 0 -> 1 -> ... -> n-1 plus one edge n-1 -> n/2: recursion would be 200000 deep
        int[][] g = new int[n][];
        for (int v = 0; v < n; v++) g[v] = new int[] { v + 1 < n ? v + 1 : n / 2 };
        int[] disc = new int[n], low = new int[n], next = new int[n];
        int[] call = new int[n], st = new int[n];       // our own call stack and Tarjan's stack
        bool[] onStack = new bool[n];
        for (int i = 0; i < n; i++) disc[i] = -1;
        int timer = 0, count = 0, largest = 0, callTop = 0, stTop = 0;
        for (int s = 0; s < n; s++) {
            if (disc[s] >= 0) continue;
            call[callTop++] = s;
            while (callTop > 0) {
                int v = call[callTop - 1];
                if (disc[v] < 0) {                      // first time we see v: the "enter" work
                    disc[v] = low[v] = timer++;
                    st[stTop++] = v;
                    onStack[v] = true;
                }
                if (next[v] < g[v].Length) {            // next[v] remembers where the loop stopped
                    int w = g[v][next[v]++];
                    if (disc[w] < 0) call[callTop++] = w;           // "recursive call"
                    else if (onStack[w]) low[v] = Math.Min(low[v], disc[w]);
                } else {                                // all edges done: the "return" work
                    callTop--;
                    if (low[v] == disc[v]) {
                        int size = 0, w;
                        do { w = st[--stTop]; onStack[w] = false; size++; } while (w != v);
                        count++;
                        largest = Math.Max(largest, size);
                    }
                    if (callTop > 0) { int p = call[callTop - 1]; low[p] = Math.Min(low[p], low[v]); }
                }
            }
        }
        Console.WriteLine("nodes: " + n + ", edges: " + n + " (chain plus one back edge)");
        Console.WriteLine("SCC count: " + count);
        Console.WriteLine("largest SCC: " + largest);
    }
}
// Time O(V + E), space O(V) on the heap - no deep recursion, so no stack overflow
